def update_intervals(intervals, new_interval):
    if not intervals:
        return [new_interval]
    if new_interval[0] <= intervals[0][0]:
        intervals.insert(0, new_interval)
    elif new_interval[1] >= intervals[-1][1]:
        intervals.append(new_interval)
    else:
        for i in range(len(intervals)):
            if intervals[i][0] <= new_interval[0] <= intervals[i][1] or intervals[i][0] <= new_interval[1] <= intervals[i][1]:
                intervals.insert(i, new_interval)
                return intervals
            if intervals[i][0] > new_interval[1]:
                intervals.insert(i, new_interval)
                return intervals
            if intervals[i][1] < new_interval[0]:
                continue
            intervals.insert(i, new_interval)
            return intervals

