def solve_helper(num, sub_set, left, right, target, result):
    if (left > right or target < left):
        return
    if (left == right and target > left):
        result.append(num + [left])
        return
    solve_helper(num, sub_set, left + 1, right, target, result)
    if left <= target - left:
        solve_helper(num + [left], sub_set, left + 1, right, target - left, result)
    return result

