import random

def solve_helper(nums, k):
    if k == 1:
        return min(nums)
    elif k == len(nums):
        return max(nums)
    else:
        pivot_index = random.randrange(len(nums))
        nums[idx := pivot_index], nums[-1] = nums[-1], nums[idx]
        _, count = partition(nums, 0, len(nums) - 1)
        if count == k - 1:
