    d = {i: -1 for i in range(n)}
    for edge in edges:
        if d[edge[0]] == -1:
            h.append([edge[0]])
            d[edge[0]] = len(h) - 1
        if d[edge[1]] == -1:
            h.append([edge[1]])
            d[edge[1]] = len(h) - 1
