def solve(intervals):
    class Heap:
        def __init__(self):
            self.items = []

        def push(self, item):
            self.items.append(item)
            self._bubble_up(len(self.items) - 1)

        def pull(self):
            if len(self.items) == 0:
                return None
            if len(self.items) == 1:
                return self.items.pop()
            result = self.items[0]
            self.items[0] = self.items.pop()
            self._bubble_down(0)
            return result

        def _bubble_up(self, index):
            parent_index = (index - 1) // 2
            if index == 0 or self.items[parent_index][1] <= self.items[index][1]:
                return
            self._swap(parent_index, index)
            self._bubble_up(parent_index)

        def _bubble_down(self, index):
            left_child_index = 2 * index + 1
            right_child_index = 2 * index + 2
            if left_child_index >= len(self.items):
                return
            if right_child_index >= len(self.items):
                if self.items[index][1] < self.items[left_child_index][1]:
                    self._swap(index, left_child_index)
                return
            if self.items[left_child_index][1] <= self.items[right_child_index][1]:
                if self.items[index][1] < self.items[left_child_index][1]:
                    self._swap(index, left_child_index)
                    self._bubble_down(left_child_index)
                return
            if self.items[index][1] < self.items[right_child_index][1]:
                self._swap(index, right_child_index)
                self._bubble_down(right_child_index)

        def _swap(self, i, j):
            self.items[i], self.items[j] = self.items[j], self.items[i]

    heap = Heap()
    for start, end in intervals:
        heap.push((-end, start))

    count = 0
    prev_end = -1
    for _ in range(len(intervals)):
        end, start = heap.pull()
        if prev_end <= start:
            prev_end = -end
        else:
            count += 1
    return count
