def has_cycle(graph):
    visited = set()

    def dfs(a, parent):
        visited.add(a)
        for b in graph[a]:
            if b not in visited:
                if dfs(b, a):
                    return True
            elif b != parent:
                return True
        return False

    for i in range(len(graph)):
        if i not in visited and dfs(i, None):
            return True
    return False

def topological_sort(graph):
    if has_cycle(graph):
        return []
    order = []
    visited = set()
    for i in range(len(graph)):
        if i not in visited:
            stack = [i]
            visited.add(i)
            while stack:
                j = stack.pop()
                order.append(j)
                for k in reversed(graph[j]):
                    if k not in visited:
                        stack.append(k)
                        visited.add(k)
    return order

