def compress(node, adj):
    for i in range(len(adj[node])):
        compressed = -1
        for j, u in enumerate(adj[node]):
            if u == node:
                compressed = i
                break

        adj[i].extend(adj.pop(node))

def recursive_topological_sort(node, adj, visited, topo, stack):
    if node in visited:
        stack.append(node)
        return stack

    visited.add(node)

    for adj_node in adj[node]:
        stack = recursive_topological_sort(adj_node, adj, visited, topo, stack)

    topo.append(node)
    return stack

