from collections import defaultdict, deque

def solve(n, prerequisites):
    def has_cycle(graph):
        visited = set()
        rec_stack = set()
        for node in graph:
            if node not in visited:
                if has_cycle_helper(graph, node, visited, rec_stack):
                    return True
        return False

    def has_cycle_helper(graph, node, visited, rec_stack):
        if node in rec_stack: return True
        if node in visited: return False
        visited.add(node)
        rec_stack.add(node)
        for neighbor in graph[node]:
            if has_cycle_helper(graph, neighbor, visited, rec_stack):
                return True
        rec_stack.remove(node)
        return False

    graph = defaultdict(set)
    indegree = [0] * n
    for a, b in prerequisites:
        graph[b].add(a)
        indegree[a] += 1

    if any(indegree[i] > 0 for i in range(n)):
        if has_cycle(graph):
            return []
    else:
        return list(range(n))

    order = []
    q = deque([i for i in range(n) if indegree[i] == 0])
    while q:
        node = q.popleft()
        order.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                q.append(neighbor)
    return order if len(order) == n else []
