def binary_search(nums, target, find_first, left, right):
    if left > right:
        return right
    mid = (left + right) // 2
    if find_first and nums[mid] == target and (mid == 0 or nums[mid - 1] < target):
        return mid
    if find_first and nums[mid] >= target:
