from collections import Counter
import heapq

def get_mode(n):
    count = Counter(n)
    for c in count:
        yield c, count[c]

def solve(nums, k):
    mode_freq = get_mode(nums)
    heap = []
    for num, freq in mode_freq:
        if freq > 0:
            heapq.heappush(heap, (-freq, num))
        elif heap and heap[0][0] == -freq:
            heapq.heappop(heap)
    return [num for _, num in sorted(heap)[:k]]
