def _solve(nums):
    ax = sorted(set(nums))
    nums = [bin_search(ax, i) for i in nums]

    stack = [0]
    visited = set([0])
    ans = 0
    for i in range(1, len(nums)):
        if nums[i] > nums[stack[-1]]:
            stack.append(i)
            visited.add(i)
        else:
            idx = bin_search(visited, nums[i])
            num = stack[idx]
            del stack[idx]
            visited.remove(num)
