class Heap:
    def __init__(self):
        self.items = []

    def push(self, priority, item):
        self.items.append((priority, item))
        self._heapify_up(len(self.items) - 1)

    def pop(self):
        if not self.items:
            return None
        if len(self.items) == 1:
            return self.items.pop(0)[1]
        result = self.items[0][1]
        self.items[0] = self.items.pop()
        self._heapify_down(0)
        return result

    def _heapify_up(self, index):
        parent = (index - 1) >> 1
        if parent < 0:
            return
        if self.items[parent][0] < self.items[index][0]:
            self._swap(parent, index)
            self._heapify_up(parent)

    def _heapify_down(self, index):
        left = (index << 1) + 1
        right = (index + 1) << 1
        largest = index
        if left < len(self.items) and self.items[left][0] > self.items[largest][0]:
            largest = left
        if right < len(self.items) and self.items[right][0] > self.items[largest][0]:
            largest = right
        if largest != index:
            self._swap(largest, index)
            self._heapify_down(largest)

    def _swap(self, i, j):
        self.items[i], self.items[j] = self.items[j], self.items[i]
