def solve(nums, k):
    def count_less(mid):
        return sum(1 for x in nums if x < mid)
    def count_eq_mid(mid):
        return sum(1 for x in nums if x == mid)
    def binary_search():
        left, right = min(nums), max(nums)
        while left < right:
            mid = (left + right) // 2
            if count_less(mid) < k - 1:
                left = mid + 1
            else:
                right = mid
        ans = right
        if count_eq_mid(ans) + count_less(ans) < k:
            if count_eq_mid(ans) - 1:
                return ans
            else:
                return ans * 2
        # case count_eq(ans) > 1
        rng = [left, ans-1]
        left_adj, right_adj = count_less(left), count_less(ans-1)
        if (count_less(ans-1) + count_eq_mid(ans)) < k: right_adj += 1
        if k <= left_adj: return rng[0]
        if k <= left_adj + count_eq_mid(ans): return min(rng)
        if k <= right_adj + count_eq_mid(ans): return ans
        return rng[1]
    return binary_search()
