class MinHeap:
    def __init__(self):
        self.heap = []

    def heappush(self, value):
        self.heap.append(value)
        self._bubble_up(self.size() - 1)

    def heappop(self):
        if self.size() == 0:
            return None
        if self.size() == 1:
            return self.heap.pop()

        value = self.heap[0]
        self.heap[0] = self.heap.pop()
        self._bubble_down(0)
        return value

    def _bubble_up(self, index):
        parent_index = (index - 1) // 2
        if parent_index == -1:
            return
        if self.heap[parent_index] > self.heap[index]:
            self.heap[parent_index], self.heap[index] = self.heap[index], self.heap[parent_index]
            self._bubble_up(parent_index)

    def _bubble_down(self, index):
        left_child_index = 2 * index + 1
        right_child_index = 2 * index + 2
        smallest_index = index

        if (
            left_child_index < self.size()
            and self.heap[left_child_index] < self.heap[smallest_index]
        ):
            smallest_index = left_child_index

        if (
            right_child_index < self.size()
            and self.heap[right_child_index] < self.heap[smallest_index]
        ):
            smallest_index = right_child_index

        if smallest_index != index:
            self.heap[smallest_index], self.heap[index] = self.heap[index], self.heap[smallest_index]
            self._bubble_down(smallest_index)

    def size(self):
        return len(self.heap)


def kth_smallest(nums, k):
    min_heap = MinHeap()
    for num in nums:
        min_heap.heappush(num)
        if min_heap.size() > k:
            min_heap.heappop()

    return min_heap.heap[0]
