import heapq

def solve(nums, k):
    counter = {}
    for num in nums:
        if num not in counter:
            counter[num] = 0
        counter[num] += 1

    heap = []
    for num in counter:
        heapq.heappush(heap, (counter[num], num))
        if len(heap) > k:
            heapq.heappop(heap)

    return heap[0][1]
